mapper.select:
select distinct u.id, u.username, u.password, u.nickname, u.real_name, u.phone, u.email, u.union_id, u.status, u.created_at, u.updated_at from sys_user u
inner join sys_user_role ur on ur.user_id = u.id inner join sys_role r on r.id = ur.role_id
and ( u.username like concat('%', #{keyword}, '%') or u.nickname like concat('%', #{keyword}, '%') or u.real_name like concat('%', #{keyword}, '%') )
and u.status = #{status}
and r.role_code = #{roleCode}
order by u.id desc

mapper.update:
update sys_user
password = #{password}, nickname = #{nickname}, real_name = #{realName}, phone = #{phone}, email = #{email}, union_id = #{unionId}, status = #{status}, updated_at = now()
where id = #{id}

mapper.select:
select count(1)
from sys_user u
inner join sys_user_role ur on ur.user_id = u.id
inner join sys_role r on r.id = ur.role_id
where u.id = #{userId}
  and r.role_code = #{roleCode}
